// Standalone project launcher, generated by Personal Skills Hub.
// Session flags are used because some desktop clients ignore project skill switches.
import fs from 'node:fs/promises';
import { spawn } from 'node:child_process';
/* PSH_CODEX_RESOLVER */
const session = JSON.parse(await fs.readFile(new URL('./session.json', import.meta.url), 'utf8'));
const override = 'skills.config=[' + session.overrides.map(s => `{path=${JSON.stringify(s.path)},enabled=${s.enabled}}`).join(',') + ']';
if (process.platform === 'win32' && override.length > 28000) {
  console.error('技能清单过长，超出 Windows 启动参数限制。请减少扫描来源或使用桌面路由模式。'); process.exit(1);
}
const args = ['-c', override, '-C', session.project, ...process.argv.slice(2)];
console.log('Personal Skills Hub · 聚焦会话（仅影响本次 Codex CLI）');
const executable = await resolveCodexCommand();
const child = spawn(executable.command, [...executable.args, ...args], { cwd: session.project, stdio: 'inherit', windowsHide: false, shell: false });
child.on('error', e => { console.error(`无法启动 Codex CLI：${e.message}`); process.exitCode = 1; });
child.on('exit', code => { process.exitCode = code ?? 1; });
